import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
const directory='/private/tmp/legendgirl-impact-observacao';await fs.mkdir(directory,{recursive:true});
const pages=await(await fetch('http://127.0.0.1:9222/json')).json();const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
let id=0;const pending=new Map();ws.onmessage=({data})=>{const m=JSON.parse(data);if(pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(JSON.stringify(m.error))):p.resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{pending.set(++id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,userGesture:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
const wait=ms=>new Promise(r=>setTimeout(r,ms));const held=new Set();const vk={ArrowRight:39,ArrowLeft:37,ArrowUp:38,ArrowDown:40,Space:32};
async function keys(next){for(const k of [...held])if(!next.has(k)){await send('Input.dispatchKeyEvent',{type:'keyUp',code:k,key:k==='Space'?' ':k,windowsVirtualKeyCode:vk[k]});held.delete(k);}for(const k of next)if(!held.has(k)){await send('Input.dispatchKeyEvent',{type:'keyDown',code:k,key:k==='Space'?' ':k,windowsVirtualKeyCode:vk[k]});held.add(k);}}
async function attack(){await send('Input.dispatchKeyEvent',{type:'keyDown',code:'Space',key:' ',windowsVirtualKeyCode:32});await send('Input.dispatchKeyEvent',{type:'keyUp',code:'Space',key:' ',windowsVirtualKeyCode:32});}
async function shot(name){const result=await send('Page.captureScreenshot',{format:'png'});await fs.writeFile(directory+'/'+name+'.png',Buffer.from(result.data,'base64'));}
const read=`(()=>{const r=game.state.toyRoomInstance?.instance,b=r?.battle,s=b?.state;if(!s)return {arena:r?.arena?.state.status};const e=s.enemy;return {mode:s.mode,transition:Boolean(s.transition),x:r.player.x,enemyX:e.x,actor:e.actor,enemyHp:e.hp,hp:s.player.hp,enemyState:e.state,attack:e.attack,enemyElapsed:e.elapsed,jump:s.jump,cooldown:s.cooldown,attackTime:s.attackTime,guard:b.enemyGuarding(),range:b.getSwordRange(e.actor),contact:b.getEnemyCollisionDistance(e.actor),history:s.history.filter(x=>['PLAYER_HIT','ENEMY_HIT','SWORD_BLOCKED','DEFEATED'].includes(x.event)),reaction:s.playerHitTime};})()`;
try{
 await send('Emulation.setDeviceMetricsOverride',{width:1200,height:720,deviceScaleFactor:1,mobile:false});
 await send('Page.navigate',{url:'http://127.0.0.1:3001/'});
 for(let i=0;i<150&&!await evaluate('Boolean(window.game)');i++)await wait(100);await evaluate('game.assetsReady');
 for(const policy of ['insistencia','esquiva']){
  await keys(new Set());await evaluate(`(()=>{const t=document.querySelector('#btn-debug-phase-toggle');if(document.querySelector('#debug-phase-panel').hidden)t.click();const s=document.querySelector('#debug-phase-select');s.value='arena';s.dispatchEvent(new Event('change',{bubbles:true}));})()`);
  const start=Date.now(),captured=new Set();let prevActor='',historySize=0,attempts=0,s;
  while(Date.now()-start<180000){
   s=await evaluate(read);if(!s.mode||s.transition){await keys(new Set());await wait(80);continue;}
   if(s.actor!==prevActor){console.log(JSON.stringify({politica:policy,inimigo:s.actor,vida:s.hp,tempo:+((Date.now()-start)/1000).toFixed(2)}));prevActor=s.actor;}
   if(s.mode!=='BATTLE'){await keys(new Set());await shot(policy+'-'+s.mode);break;}
   const toward=s.enemyX>=s.x?'ArrowRight':'ArrowLeft',distance=Math.abs(s.enemyX-s.x),next=new Set();let strike=false;
   if(policy==='insistencia'){next.add(toward);strike=s.cooldown===0;}
   else{
    if(distance>Math.min(s.range-12,s.contact+25))next.add(toward);
    if(s.enemyState==='ATTACK'){
     const end=s.attack==='Toy Leap'?96:72,crouch=['Laser Beam','Rocket Punch'].includes(s.attack);
     if(crouch&&s.enemyElapsed<end)next.add('ArrowDown');
     const jumpAt=s.attack==='Toy Leap'?48:24;
     if(!crouch&&s.enemyElapsed>=jumpAt&&s.enemyElapsed<jumpAt+14&&s.jump===0)next.add('ArrowUp');
     strike=s.enemyElapsed>=end&&!s.guard&&s.jump<85&&distance<s.range&&s.cooldown===0;
    }else strike=!['HIT','ENRAGE'].includes(s.enemyState)&&s.jump<85&&distance<s.range-5&&s.cooldown===0;
   }
   await keys(next);if(strike){await attack();attempts++;}
   if(s.history.length>historySize){const event=s.history.at(-1);console.log(JSON.stringify({politica:policy,event,distancia:+distance.toFixed(1),estado:s.enemyState,preparacao:+s.enemyElapsed.toFixed(1)}));historySize=s.history.length;
    const key=policy+'-'+s.actor+'-'+event.event;if(!captured.has(key)){captured.add(key);await shot(key);}}
   await wait(60);
  }
  const result={politica:policy,resultado:s?.mode,segundos:+((Date.now()-start)/1000).toFixed(2),tentativasEspada:attempts,vida:s?.hp,eventos:s?.history};
  console.log('RESULTADO '+JSON.stringify(result));await fs.writeFile(directory+'/'+policy+'.json',JSON.stringify(result,null,2));
  if(policy==='esquiva')assert.equal(s?.mode,'VICTORY','Gameplay com controles reais precisa vencer');
 }
}finally{await keys(new Set());ws.close();}
